changeSet.sql:
DO $$ BEGIN IF to_regclass('portal_menu') IS NULL THEN RETURN; END IF;
IF to_regclass('portal_menu_visibility') IS NOT NULL THEN WITH RECURSIVE catalog_root AS ( SELECT id FROM portal_menu WHERE parent_id IS NULL AND ( lower(name) = 'sys.nav.portal.catalog' OR lower(path) = 'catalog' OR (metadata IS NOT NULL AND lower(metadata) LIKE '%"sectionkey":"catalog"%') ) ), catalog_tree AS ( SELECT m.id, m.parent_id, m.name, m.path, m.component, m.metadata FROM portal_menu m JOIN catalog_root r ON m.id = r.id UNION ALL SELECT c.id, c.parent_id, c.name, c.path, c.component, c.metadata FROM portal_menu c JOIN catalog_tree p ON c.parent_id = p.id ), doomed_seed AS ( SELECT id FROM catalog_tree WHERE lower(path) IN ('domains', 'subject-domains', 'subjectdomains') OR (metadata IS NOT NULL AND ( lower(metadata) LIKE '%"entrykey":"domains"%' OR lower(metadata) LIKE '%"entrykey":"subjectdomains"%' OR lower(metadata) LIKE '%"entrykey":"catalogdomains"%' )) OR (component IS NOT NULL AND ( lower(component) LIKE '%/pages/catalog/datadomainmanagementpage%' OR lower(component) LIKE '%/pages/catalog/domainslistpage%' )) ), doomed AS ( SELECT id FROM doomed_seed UNION ALL SELECT m.id FROM portal_menu m JOIN doomed d ON m.parent_id = d.id ) DELETE FROM portal_menu_visibility v WHERE v.menu_id IN (SELECT id FROM doomed); END IF;
WITH RECURSIVE catalog_root AS ( SELECT id FROM portal_menu WHERE parent_id IS NULL AND ( lower(name) = 'sys.nav.portal.catalog' OR lower(path) = 'catalog' OR (metadata IS NOT NULL AND lower(metadata) LIKE '%"sectionkey":"catalog"%') ) ), catalog_tree AS ( SELECT m.id, m.parent_id, m.name, m.path, m.component, m.metadata FROM portal_menu m JOIN catalog_root r ON m.id = r.id UNION ALL SELECT c.id, c.parent_id, c.name, c.path, c.component, c.metadata FROM portal_menu c JOIN catalog_tree p ON c.parent_id = p.id ), doomed_seed AS ( SELECT id FROM catalog_tree WHERE lower(path) IN ('domains', 'subject-domains', 'subjectdomains') OR (metadata IS NOT NULL AND ( lower(metadata) LIKE '%"entrykey":"domains"%' OR lower(metadata) LIKE '%"entrykey":"subjectdomains"%' OR lower(metadata) LIKE '%"entrykey":"catalogdomains"%' )) OR (component IS NOT NULL AND ( lower(component) LIKE '%/pages/catalog/datadomainmanagementpage%' OR lower(component) LIKE '%/pages/catalog/domainslistpage%' )) ), doomed AS ( SELECT id FROM doomed_seed UNION ALL SELECT m.id FROM portal_menu m JOIN doomed d ON m.parent_id = d.id ) DELETE FROM portal_menu m WHERE m.id IN (SELECT id FROM doomed); END $$;
